CREATE TABLE t1(a1 INTEGER PRIMARY KEY, b1 INT); CREATE TABLE t2(c2 INT, d2 INTEGER PRIMARY KEY); CREATE TABLE t3(e3 INTEGER PRIMARY KEY); INSERT INTO t1 VALUES(33,0); INSERT INTO t2 VALUES(33,1),(33,2);
SELECT t1.a1, t2.d2 FROM (t1 LEFT JOIN t3 ON t3.e3=t1.b1) JOIN t2 ON t2.c2=t1.a1 WHERE t1.a1=33 ORDER BY t2.d2 DESC;
